/** UI review suggestions are explicit interpretation data, never edits to a source. */
export interface SourceChoiceMemory {sourceSnapshotId:string;interpretation:ContraDbInterpretation;}
export interface SourceChoiceSuggestion {rowId?:string;kind:'conventional-give-take'|'conventional-ring-pass'|'ricochet-interpretation'|'conventional-circulate'|'gyre-interpretation'|'conventional-petronella'|'conventional-wave'|'conventional-rollaway'|'conventional-timing'|'formation-derived'|'endpoint-progression'|'conventional-rlt'|'conventional-hall'|'source-annotation'|'event-policy'|'source-circulation'|'conventional-twirl'|'prose-review'|'ordinary-hey-context'|'conventional-promenade'|'conventional-hall-entry'|'qualifier-interpretation'|'remembered';message:string;}
export interface SourceReviewPreparation {result:ContraDbImportResult;interpretation:ContraDbInterpretation;suggestions:SourceChoiceSuggestion[];savedArchive:boolean;}
const copy=<T>(value:T):T=>JSON.parse(JSON.stringify(value));
export function isSavedContraDbInterpretation(input:string):boolean {
 if(!input.trimStart().startsWith('{'))return false;
 try{return JSON.parse(input)?.schema==='contra-studio/contradb-interpretation';}catch{return false;}
}
