 if(hasMadRobinSource(baseline.record)){const rows=interpretation.rows??={};for(const [i,direction]of[[0,'clockwise'],[6,'counterclockwise']]as const){rows[baseline.record.rows[i].id]={madRobin:{orbitRelation:'neighbor',facingRelation:'partner',frontRole:'robin',direction,amount:1}};suggestions.push({rowId:baseline.record.rows[i].id,kind:'qualifier-interpretation',message:MAD_ROBIN_ROW_CHOICE_DESCRIPTION});}interpretation.madRobinHook={sourceSnapshotId:baseline.record.snapshotId,meaning:'old-neighbor-full-return-then-next-neighbor',sourceText:baseline.record.hook};interpretation.madRobinPolicy=copy(CONVENTIONAL_MAD_ROBIN_POLICY);suggestions.push({kind:'source-annotation',message:MAD_ROBIN_HOOK_CHOICE_DESCRIPTION},{kind:'qualifier-interpretation',message:MAD_ROBIN_POLICY_CHOICE_DESCRIPTION});}

 if(!hasMadRobinSource(baseline.record)){for(const row of baseline.record.rows){const shape=madRobinRowSource(row);if(shape?.direction){((interpretation.rows??={})[row.id]??={}).madRobin={orbitRelation:'neighbor',facingRelation:'partner',frontRole:'robin',direction:shape.direction,amount:1};suggestions.push({rowId:row.id,kind:'qualifier-interpretation',message:madRobinRowDescription(row)});}}}
 if(releasedCircleTransitionNote(baseline.record)){interpretation.notesReview='released-circle-transition';suggestions.push({kind:'prose-review',message:releasedCircleTransitionNote(baseline.record)!});}
 if(hasOrderedCircleCompletionNote(baseline.record)||releasedCircleTransitionNote(baseline.record)){const row=baseline.record.rows.at(-1)!;((interpretation.rows??={})[row.id]??={}).circleCompletion=copy(CONVENTIONAL_CIRCLE_COMPLETION);suggestions.push({rowId:row.id,kind:'qualifier-interpretation',message:CIRCLE_COMPLETION_CHOICE_DESCRIPTION});}

 for(const row of baseline.record.rows)if(rollawaySource(row)){((interpretation.rows??={})[row.id]??={}).rollaway={direction:'left-to-right'};suggestions.push({rowId:row.id,kind:'qualifier-interpretation',message:rollawayDescription(row)});}
 if(neighborDosidoGyreNote(baseline.record)){interpretation.notesReview='terminal-dosido-gyre';suggestions.push({kind:'prose-review',message:NEIGHBOR_DOSIDO_GYRE_NOTE_DESCRIPTION});}
