 if(baseline.diagnostics.some(d=>d.code==='ring-twirl-choice')){interpretation.ringTwirl=copy(CONVENTIONAL_RING_TWIRL);suggestions.push({kind:'qualifier-interpretation',message:RING_TWIRL_CHOICE_DESCRIPTION});}
