 const history=corroboratedSourceHistory(baseline.record);
 if(history){interpretation.notesReview='corroborated-history';suggestions.push({kind:'prose-review',message:history.kind==='phrase-summary'?`Review the corroborated table summary and attributed history: ${history.reason} Clear this selection to leave the source note unresolved.`:`Review the current-version/history distinction: ${history.reason} Clear this selection to leave the historical alternative unresolved.`});}
 if(baseline.diagnostics.some(d=>d.code==='source-notes-style-review')){interpretation.notesReview='corroborated-style-and-provenance';suggestions.push({kind:'prose-review',message:'Review the source note: its requested wrist-grip left-star → left-allemande transition must be represented by the typed contact graph. The remaining authorship, title history and dates are retained as provenance. This selection cannot waive a different movement instruction.'});}
 if(baseline.record.notes&&classifySourceProse(baseline.record.notes)==='provenance-candidate'){interpretation.notesReview='provenance-only';suggestions.push({kind:'prose-review',message:'Suggested provenance-only note review: the text appears to be attribution, dedication or history and contains no recognized motion/end-effect terms. Read the retained note before accepting; clear this classification if it changes how the dance is done.'});}
 const retracted=retractedSourceAttribution(baseline.record);if(retracted){interpretation.notesReview='provenance-only';suggestions.push({kind:'prose-review',message:retracted});}
