  if(baseline.eventFamily==='improper-star-whirl'||baseline.eventFamily==='improper-mad-robin')suggestions.push({kind:'event-policy',message:baseline.eventFamily==='improper-star-whirl'?'Review waiting the first four counts, exchanging at the same physical end over the next eight, then waiting with zero pre-event preparation.':'Review the first-eight-count same-end exchange, then waiting while facing the persistent partner; no additional reentry preparation counts.'});
  if(baseline.eventFamily==='improper-six-two')suggestions.push({kind:'event-policy',message:'Review the separate source-omitted end policy: wait four counts, exchange at the same physical end over eight, then wait with zero pre-event preparation and lark-left placement. The terminal marker remains source-explicit.'});
  if(baseline.eventFamily==='improper-swing-start'){interpretation.swingStart={entry:'closed-neighbor-frame',return:'next-neighbor-swing'};suggestions.push({kind:'qualifier-interpretation',message:'Review the source-omitted initial/return convention: begin with active neighbors already held in a closed swing frame; finish the final four-count passage in the next neighbor frame or waiting end. The first swing count turns immediately, and the final passage keeps all four source counts.'});suggestions.push({kind:'event-policy',message:'Review the separate finite-end policy: wait the first four counts, exchange at the same end over the next eight, then wait and prepare the next neighbor frame during the final four counts, in lark-left placement. The source only supplies the terminal progression.'});}
