  if(baseline.eventFamily==='becket-ccw-star')suggestions.push({kind:'event-policy',message:'The source explicitly specifies counterclockwise Becket and new neighbors after the full star. Review a separate eight-count same-end exchange, lark-left waiting arrangement and zero pre-event stance-preparation counts; those end details are not supplied by the source.'});
