  suggestions.push({kind:'event-policy',message:`Review the ${baseline.eventFamily==='improper-ring-start'?'opening-ring family’s final endpoint progression':'source progression'}: after the ${baseline.eventFamily==='improper-ring-start'?'final passage':'marked figure'}, bind the next neighbors. Out couples make an eight-count turn at that same end, with ${reversed?'lark on the right and robin on the left, matching the source end note when supplied':'lark on the left and robin on the right, a conventional modeled end policy'}. No source time or synthetic travel is added.`});
