   (interpretation.rows??={})[row.source.id]={passThrough:{relation:'neighbor',passingShoulder:'right'}};suggestions.push({rowId:row.source.id,kind:'conventional-ring-pass',message:`${row.source.phrase}, row ${row.source.index+1}: review a right-shoulder passage with the current neighbor, from the source's preceding ring balance to the progressed next neighbors. The source gives four counts but omits this shoulder and crossing relation; the full endpoint must validate.`});
